void unit_test_partition_empty_segment(void) {
    // Setup: create an array with one element, partition on a zero-length segment
    const int values[] = {42};
    int size = 1;
    int *arr = create_int_test_array(values, size);
    int low = 0;
    int high = -1; // high < low, so the loop is not entered

    // Test: call partition on empty segment (should not modify array, returns low)
    int pivot_index = partition(arr, low, high);

    // Assertions
    assert_int_equal(pivot_index, low); // Should return low (0)
    assert_array_equal(arr, values, size); // Array should remain unchanged

    // Cleanup
    cleanup_int_test_array(arr);
}
